#[test]
fn html_rows_and_a_restart_cannot_certify_old_windows_or_turn_losses_into_zero(){
    use tor_traffic_behavior::{domain::html_health::HtmlHealthPeriod,services::observed_audience::ObservedPeriod};
    use tor_recommendations::services::flow_signals::{evaluate,Rule,Status};
    let period=ObservedPeriod{from_epoch:0,until_epoch:86400,from_utc:"a".into(),until_utc:"b".into(),hours:vec![],surfaces:[None;4],sources:[None;4],saved_total:Some(100),recorded_hours:24,weekday_hour:[[None;24];7],recorded_slots:[[0;24];7],expected_slots:[[0;24];7]};
    let report=ObservedAudienceReport{days:1,time_zone:"UTC".into(),measured_at_utc:"now".into(),current:ObservedPeriod{saved_total:Some(20),..period.clone()},previous:period,persisted_discards:0};
    let mut snapshot=(report,HtmlHealthReport{until_epoch:86400,current:HtmlHealthPeriod::default(),previous:HtmlHealthPeriod::default()});
    assert_eq!(evaluate(Rule::HtmlChange,html(Some(&snapshot))).unwrap().status,Status::Unknown);
    assert_eq!(evaluate(Rule::HtmlQuality,html(Some(&snapshot))).unwrap().status,Status::Unknown);
    snapshot.1.current.confirmed_hours=24;
    snapshot.1.previous.confirmed_hours=24;
    assert_eq!(evaluate(Rule::HtmlChange,html(Some(&snapshot))).unwrap().status,Status::Active);
    snapshot.1.previous.loss_hours=1;
    assert_eq!(evaluate(Rule::HtmlChange,html(Some(&snapshot))).unwrap().status,Status::Unknown);
    snapshot.0.previous.saved_total=None;
    assert_eq!(html(Some(&snapshot)).previous,None);
    snapshot.1.previous.loss_hours=0;
    assert_eq!(html(Some(&snapshot)).previous,Some(0),"only a fully acknowledged empty window is measured zero");
    snapshot.1.until_epoch+=3600;
    assert!(!html(Some(&snapshot)).available);
}
